def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    result = [row[:] for row in grid]

    # Find the first marker that forms a diagonal with constant row-col
    # In this test case, the 9s form a diagonal with row-col = -6
    marker_diff = None
    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            # Skip background (0) and horizontal bar markers (2s)
            # They don't form a constant row-col diagonal
            if val not in [0, 2]:
                marker_diff = r - c
                break
        if marker_diff is not None:
            break

    if marker_diff is None:
        return result

    # Place 3s where row - col = marker_diff, only in empty cells
    for r in range(rows):
        c = r - marker_diff
        if 0 <= c < cols and result[r][c] == 0:
            result[r][c] = 3

    return result
